function computeColumns(viewport, sidebar, explorer, details) {
	const s = sidebar === 0 ? COLLAPSED_SIDEBAR_WIDTH : clampWidth(sidebar, 264, 420);
	const e0 = explorer === 0 ? 0 : clampWidth(explorer, 200, 420);
	const d0 = details === 0 ? 0 : clampWidth(details, 300, 520);
	if (s + e0 + d0 + 640 <= viewport) return {
		sidebar: s,
		explorer: e0,
		center: viewport - s - e0 - d0,
		details: d0
	};
	const d1 = d0 === 0 ? 0 : Math.max(300, viewport - s - e0 - 640);
	if (s + e0 + d1 + 640 <= viewport) return {
		sidebar: s,
		explorer: e0,
		center: 640,
		details: d1
	};
	return {
		sidebar: s,
		explorer: e0,
		center: Math.max(0, viewport - s - e0),
		details: 0
	};
}
